package lt.chupchik.runelite.haprofit;

import net.runelite.api.ItemLayer;

final class GroundDrop
{
	final int itemId;
	final String name;
	final ItemLayer layer;
	final int haEach;
	final long geEach;
	final boolean tradeable;
	int quantity;

	GroundDrop(int itemId, String name, ItemLayer layer, int haEach,
		long geEach, boolean tradeable, int quantity)
	{
		this.itemId = itemId;
		this.name = name;
		this.layer = layer;
		this.haEach = haEach;
		this.geEach = geEach;
		this.tradeable = tradeable;
		this.quantity = quantity;
	}

	long haTotal()
	{
		return (long) haEach * quantity;
	}

	long geTotal()
	{
		return geEach * quantity;
	}

	long haMinusGePerItem()
	{
		return (long) haEach - geEach;
	}
}

package lt.chupchik.runelite.haprofit;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("chupchik-ha-profit-ground")
public interface HaProfitGroundConfig extends Config
{
	@ConfigItem(
		keyName = "natureRuneGePrice",
		name = "Nature rune GE price (auto)",
		description = "Current Nature rune GE price for reference only. It is not subtracted from HA-GE. Updated automatically; manual edits are ignored.",
		position = 0
	)
	default String natureRuneGePrice()
	{
		return "Waiting for game tick...";
	}

	@ConfigItem(
		keyName = "profitColor",
		name = "HA highlight color",
		description = "Color of the entire (HA: ...) segment when HA-GE meets the threshold, leaving GE unchanged",
		position = 2
	)
	@Alpha
	default Color profitColor()
	{
		return new Color(0, 255, 100);
	}

	@ConfigItem(
		keyName = "minProfit",
		name = "Minimum HA - GE (gp)",
		description = "Minimum HA minus GE per item. 0 = green when HA equals or exceeds GE. Nature rune is not deducted.",
		position = 1
	)
	@Range(min = 0)
	default int minProfit()
	{
		return 0;
	}
}

package lt.chupchik.runelite.haprofit;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.grounditems.GroundItemsConfig;
import net.runelite.client.plugins.grounditems.config.ItemHighlightMode;
import net.runelite.client.plugins.grounditems.config.PriceDisplayMode;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TextComponent;
import net.runelite.client.util.QuantityFormatter;

/** Paint only the HA number above RuneLite's existing Ground Items label. */
public class HaProfitGroundOverlay extends Overlay
{
	private static final int MAX_DISTANCE = 2500;
	private static final int OFFSET_Z = 20;
	private static final int STRING_GAP = 15;

	private final Client client;
	private final HaProfitGroundPlugin plugin;
	private final HaProfitGroundConfig config;
	private final GroundItemsConfig groundConfig;
	private final TextComponent textComponent = new TextComponent();
	private final Map<WorldPoint, Integer> offsetMap = new HashMap<>();
	private final StringBuilder label = new StringBuilder();

	@Inject
	public HaProfitGroundOverlay(Client client, HaProfitGroundPlugin plugin,
		HaProfitGroundConfig config, ConfigManager configManager)
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_HIGHEST);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		// Ground Items belongs to a separate plugin injector; obtain its config
		// using ConfigManager so our plugin can load independently.
		this.groundConfig = configManager.getConfig(GroundItemsConfig.class);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		ItemHighlightMode highlightMode = groundConfig.itemHighlightMode();
		if (groundConfig.priceDisplayMode() != PriceDisplayMode.BOTH
			|| highlightMode == ItemHighlightMode.MENU
			|| highlightMode == ItemHighlightMode.NONE
			|| groundConfig.showHighlightedOnly())
		{
			return null;
		}

		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		LocalPoint playerLocation = player.getLocalLocation();
		FontMetrics fm = graphics.getFontMetrics();
		offsetMap.clear();

		for (GroundDrop drop : plugin.getDrops())
		{
			WorldView view = drop.layer.getWorldView();
			LocalPoint location = LocalPoint.fromWorld(view, drop.layer.getWorldLocation());
			if (location == null || (location.getWorldView() == WorldView.TOPLEVEL
				&& playerLocation.distanceTo(location) > MAX_DISTANCE))
			{
				continue;
			}
			// Hidden low-value drops do not consume a text line in Ground Items.
			// A manually highlighted low-value item is an acknowledged edge case.
			if (drop.geTotal() < groundConfig.getHideUnderValue()
				&& drop.haTotal() < groundConfig.getHideUnderValue())
			{
				continue;
			}

			// Drops that do not meet the HA-GE threshold still occupy a line.
			int offset = offsetMap.compute(drop.layer.getWorldLocation(),
				(k, old) -> old == null ? 0 : old + 1);

			if (drop.itemId == ItemID.COINS || !drop.tradeable
				|| drop.geEach <= 0 || drop.haEach <= 0
				|| drop.haMinusGePerItem() < config.minProfit())
			{
				continue;
			}

			label.append(drop.name);
			if (drop.quantity > 1)
			{
				label.append(" (")
					.append(QuantityFormatter.quantityToStackSize(drop.quantity))
					.append(')');
			}
			label.append(" (GE: ")
				.append(QuantityFormatter.quantityToStackSize(drop.geTotal()))
				.append(" gp)");
			String prefix = label.toString();
			String haPart = " (HA: " + QuantityFormatter.quantityToStackSize(drop.haTotal()) + " gp)";
			label.append(haPart);
			String fullText = label.toString();
			label.setLength(0);

			Point textPoint = Perspective.getCanvasTextLocation(client, graphics,
				location, fullText, drop.layer.getHeight() + OFFSET_Z);
			if (textPoint == null)
			{
				continue;
			}

			textComponent.setText(haPart);
			textComponent.setColor(config.profitColor());
			textComponent.setOutline(groundConfig.textOutline());
			textComponent.setPosition(new java.awt.Point(
				textPoint.getX() + fm.stringWidth(prefix),
				textPoint.getY() - STRING_GAP * offset));
			textComponent.render(graphics);
		}
		return null;
	}
}

package lt.chupchik.runelite.haprofit;

import com.google.common.collect.HashBasedTable;
import com.google.common.collect.Table;
import com.google.inject.Provides;
import java.util.Collection;
import javax.inject.Inject;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemLayer;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.ItemQuantityChanged;
import net.runelite.api.events.ItemSpawned;
import net.runelite.api.events.WorldViewUnloaded;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "HA Profit Ground Items",
	description = "Color HA values when HA is at least GE inside Ground Items labels",
	tags = {"ground", "loot", "alchemy", "profit"},
	internalName = "ha-profit-ground-items"
)
public class HaProfitGroundPlugin extends Plugin
{
	private static final String CONFIG_GROUP = "chupchik-ha-profit-ground";
	private static final String RUNE_PRICE_KEY = "natureRuneGePrice";

	@Inject private ItemManager itemManager;
	@Inject private OverlayManager overlayManager;
	@Inject private HaProfitGroundOverlay overlay;
	@Inject private ConfigManager configManager;

	// Match the iteration order used by RuneLite's built-in Ground Items plugin.
	private final Table<WorldPoint, Integer, GroundDrop> drops = HashBasedTable.create();
	private long natureRunePrice;

	@Provides
	HaProfitGroundConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(HaProfitGroundConfig.class);
	}

	@Override
	protected void startUp()
	{
		drops.clear();
		// Item prices require the client thread; onGameTick will populate this value.
		natureRunePrice = 0L;
		updateNatureRunePriceDisplay();
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		drops.clear();
		natureRunePrice = 0L;
		configManager.setConfiguration(CONFIG_GROUP, RUNE_PRICE_KEY, "Plugin disabled");
	}

	Collection<GroundDrop> getDrops()
	{
		return drops.values();
	}

	long getNatureRunePrice()
	{
		return natureRunePrice;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// Work outside the frame-render loop.
		natureRunePrice = itemManager.getItemPrice(ItemID.NATURERUNE);
		updateNatureRunePriceDisplay();
	}

	private void updateNatureRunePriceDisplay()
	{
		String value = natureRunePrice > 0 ? natureRunePrice + " gp" : "Waiting for game tick...";
		if (!value.equals(configManager.getConfiguration(CONFIG_GROUP, RUNE_PRICE_KEY)))
		{
			configManager.setConfiguration(CONFIG_GROUP, RUNE_PRICE_KEY, value);
		}
	}

	@Subscribe
	public void onWorldViewUnloaded(WorldViewUnloaded event)
	{
		drops.values().removeIf(drop -> drop.layer.getWorldView() == event.getWorldView());
	}

	@Subscribe
	public void onItemSpawned(ItemSpawned event)
	{
		Tile tile = event.getTile();
		TileItem item = event.getItem();
		WorldPoint worldPoint = tile.getWorldLocation();
		GroundDrop existing = drops.get(worldPoint, item.getId());
		if (existing != null)
		{
			existing.quantity += item.getQuantity();
			return;
		}

		ItemLayer layer = tile.getItemLayer();
		if (layer == null)
		{
			return;
		}
		ItemComposition composition = itemManager.getItemComposition(item.getId());
		int geId = composition.getNote() != -1 ? composition.getLinkedNoteId() : item.getId();
		long geEach = geId == ItemID.COINS ? 1 : itemManager.getItemPrice(geId);
		int haEach = geId == ItemID.COINS ? 1 : composition.getHaPrice();
		drops.put(worldPoint, item.getId(), new GroundDrop(
			item.getId(), composition.getName(), layer, haEach, geEach,
			composition.isGeTradeable(), item.getQuantity()));
	}

	@Subscribe
	public void onItemDespawned(ItemDespawned event)
	{
		GroundDrop drop = drops.get(event.getTile().getWorldLocation(), event.getItem().getId());
		if (drop == null)
		{
			return;
		}
		if (drop.quantity <= event.getItem().getQuantity())
		{
			drops.remove(event.getTile().getWorldLocation(), event.getItem().getId());
		}
		else
		{
			drop.quantity -= event.getItem().getQuantity();
		}
	}

	@Subscribe
	public void onItemQuantityChanged(ItemQuantityChanged event)
	{
		GroundDrop drop = drops.get(event.getTile().getWorldLocation(), event.getItem().getId());
		if (drop != null)
		{
			drop.quantity += event.getNewQuantity() - event.getOldQuantity();
		}
	}
}

package lt.chupchik.runelite.haprofit;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GroundDropTest
{
	@Test
	public void haAboveGeMeetsTheConfiguredDifference()
	{
		GroundDrop drop = new GroundDrop(1, "Example", null, 1200, 900, true, 2);
		assertEquals(300L, drop.haMinusGePerItem());
		assertTrue(drop.haMinusGePerItem() >= 0);
		assertTrue(drop.haMinusGePerItem() >= 300);
		assertFalse(drop.haMinusGePerItem() >= 301);
		assertEquals(2400L, drop.haTotal());
		assertEquals(1800L, drop.geTotal());
	}

	@Test
	public void equalHaAndGeMeetsTheZeroDifferenceThreshold()
	{
		GroundDrop drop = new GroundDrop(1, "Example", null, 1200, 1200, true, 1);
		assertEquals(0L, drop.haMinusGePerItem());
		assertTrue(drop.haMinusGePerItem() >= 0);
		assertFalse(drop.haMinusGePerItem() >= 1);
	}

	@Test
	public void haBelowGeDoesNotMeetTheZeroDifferenceThreshold()
	{
		GroundDrop drop = new GroundDrop(1, "Example", null, 900, 1200, true, 1);
		assertEquals(-300L, drop.haMinusGePerItem());
		assertFalse(drop.haMinusGePerItem() >= 0);
	}
}

